#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>

/* Blockchain smart contract runtime - async callback handler */
/* Simulates a contract execution environment with graceful shutdown */

typedef struct callback_node {
    void (*handler)(void *ctx, uint64_t block_height);
    void *context;
    uint64_t trigger_block;
    struct callback_node *next;
    uint32_t ref_count;
    bool cancelled;
} callback_node_t;

typedef struct {
    uint8_t state_root[32];
    uint64_t balance;
    char owner[64];
    uint32_t nonce;
} contract_state_t;

typedef struct {
    callback_node_t *pending_head;
    callback_node_t *executing;
    contract_state_t *state;
    bool shutdown_requested;
    bool drain_complete;
    uint64_t current_block;
    uint32_t active_callbacks;
} runtime_ctx_t;

static runtime_ctx_t g_runtime;

void transfer_callback(void *ctx, uint64_t block_height) {
    contract_state_t *st = (contract_state_t *)ctx;
    if (st && block_height > 0) {
        st->balance -= 100;
        st->nonce++;
    }
}

void stake_callback(void *ctx, uint64_t block_height) {
    contract_state_t *st = (contract_state_t *)ctx;
    if (st && block_height > 0) {
        st->balance += (block_height * 10);
        st->nonce++;
    }
}

callback_node_t *register_callback(
    void (*handler)(void *, uint64_t),
    void *context,
    uint64_t trigger_block
) {
    callback_node_t *node = (callback_node_t *)malloc(sizeof(callback_node_t));
    if (!node) return NULL;

    node->handler = handler;
    node->context = context;
    node->trigger_block = trigger_block;
    node->next = g_runtime.pending_head;
    node->ref_count = 1;
    node->cancelled = false;

    g_runtime.pending_head = node;
    g_runtime.active_callbacks++;
    return node;
}

void release_callback(callback_node_t *node) {
    if (!node) return;
    node->ref_count--;
    if (node->ref_count == 0) {
        free(node);
    }
}

/* Drain pending callbacks during shutdown - processes remaining work */
static void drain_pending_callbacks(runtime_ctx_t *rt) {
    callback_node_t *current = rt->pending_head;
    callback_node_t *prev = NULL;

    while (current != NULL) {
        callback_node_t *next = current->next;

        if (current->cancelled) {
            /* Remove cancelled nodes from list */
            if (prev == NULL) {
                rt->pending_head = next;
            } else {
                prev->next = next;
            }
            release_callback(current);
            rt->active_callbacks--;
        } else if (current->trigger_block <= rt->current_block) {
            /* Execute ready callbacks */
            rt->executing = current;
            current->handler(current->context, rt->current_block);
            rt->executing = NULL;

            if (prev == NULL) {
                rt->pending_head = next;
            } else {
                prev->next = next;
            }
            release_callback(current);
            rt->active_callbacks--;
        } else {
            prev = current;
        }
        current = next;
    }
}

/* Graceful shutdown: free state, then drain remaining callbacks */
void initiate_shutdown(runtime_ctx_t *rt) {
    rt->shutdown_requested = true;

    /* Phase 1: Persist and release contract state */
    /* In production this would serialize to storage */
    if (rt->state) {
        /* Zero-out sensitive data before freeing */
        memset(rt->state->owner, 0, sizeof(rt->state->owner));
        free(rt->state);
        rt->state = NULL;
    }

    /* Phase 2: Drain any pending callbacks that are ready */
    /* Note: callbacks may still reference the now-freed state */
    drain_pending_callbacks(rt);

    rt->drain_complete = true;
}

/* Simulate contract lifecycle */
int main(void) {
    memset(&g_runtime, 0, sizeof(g_runtime));

    /* Initialize contract state */
    g_runtime.state = (contract_state_t *)malloc(sizeof(contract_state_t));
    if (!g_runtime.state) return 1;

    memset(g_runtime.state->state_root, 0xAB, 32);
    g_runtime.state->balance = 10000;
    strncpy(g_runtime.state->owner, "0xDEADBEEF", 63);
    g_runtime.state->nonce = 0;
    g_runtime.current_block = 100;

    /* Register async callbacks that reference contract state */
    register_callback(transfer_callback, g_runtime.state, 100);
    register_callback(stake_callback, g_runtime.state, 100);
    register_callback(transfer_callback, g_runtime.state, 200);

    /* Simulate blocks advancing */
    g_runtime.current_block = 150;

    /* Trigger graceful shutdown */
    initiate_shutdown(&g_runtime);

    /* Cleanup remaining nodes */
    callback_node_t *n = g_runtime.pending_head;
    while (n) {
        callback_node_t *tmp = n->next;
        release_callback(n);
        n = tmp;
    }

    return 0;
}
